const items = $input.all();
const results = [];

// Проходимся по каждому элементу
for (const item of items) {
  const msg = item.json.message || {}; 

  // Берем текст сообщения из Telegram
  const text = msg.text || '';

  // Извлекаем название товара (очищаем от стартовых фраз, если они есть)
  const product = text.replace(/^(найди производство|поиск фабрики|хочу найти|новый товар| найти| найди|)[:\s]*/i, '').trim() || text.trim();

  // Ищем сертификаты и MOQ в тексте сообщения, если их там написали
  const certMatch = text.match(/(GMP|ISO|HACCP|FDA|CE|SGS|Halal|Kosher)/gi);
  const moqMatch = text.match(/MOQ[:\s]*(\d+)/i);

  results.push({
    // Идентификатором делаем ID сообщения или ID чата, чтобы n8n не ругался на отсутствие taskId
    taskId: msg.message_id ? String(msg.message_id) : String(Date.now()), 
    product: product || 'Не указан',
    notes: text, // Сам текст сообщения уходит в примечания
    requiredCerts: certMatch ? [...new Set(certMatch)].join(', ') : 'не указаны',
    moq: moqMatch ? moqMatch[1] : 'не указано',
    // Имя пользователя из Telegram вместо исполнителя Asana
    assignee: msg.from?.first_name || 'Telegram User', 
    searchDate: new Date().toLocaleDateString('ru-RU')
  });
}

return results;

const raw = $input.first().json.output || '';
const cleaned = raw.replace(/```json/gi,'').replace(/```/g,'').trim();
let factories;
try { factories = JSON.parse(cleaned); }
catch(e) {
  const m = cleaned.match(/\[.*\]/s);
  if(m) factories = JSON.parse(m[0]);
  else throw new Error('Cannot parse factory list: ' + cleaned.substring(0,200));
}
if(!Array.isArray(factories)) factories = [factories];
const ctx = $('Parse ТЗ').first().json;
return [{ json: { ...ctx, factories, factoryCount: factories.length } }];

// 1. ПОЛУЧЕНИЕ ДАННЫХ ИЗ ПРЕДЫДУЩИХ НОД
const mainData = $('Parse Factory List').first().json;
const aiNode = $('AI Agent — Compare & Rank').first().json;

// Пытаемся распарсить JSON, если Агент вернул строку
let aiOutput;
try {
  aiOutput = typeof aiNode.output === 'string' ? JSON.parse(aiNode.output) : aiNode.output;
} catch (e) {
  // На случай, если ИИ вернул markdown-разметку ```json ... ```
  try {
    const cleanString = aiNode.output.replace(/```json/g, '').replace(/```/g, '').trim();
    aiOutput = JSON.parse(cleanString);
  } catch (err) {
    aiOutput = aiNode; 
  }
}

// 2. КАРТА ТЕЛЕФОНОВ (Резервная копия из первой ноды)
const phoneMap = {};
const originalFactories = mainData.factories || [];

originalFactories.forEach(f => {
  // Исправлено: ищем любые вариации ключа телефона в исходных данных
  const originalPhone = f.phoneNumber || f['Phone number'] || f.phone;
  if (originalPhone && f.factoryName) {
    const key = f.factoryName.replace(/[^a-zа-я0-9]/gi, '').toLowerCase();
    phoneMap[key] = originalPhone;
  }
});

// 3. РАНЖИРОВАНИЕ
const ranked = aiOutput.rankedFactories || [];

// 4. ГЕНЕРАЦИЯ ТЕКСТА ДЛЯ TELEGRAM
let tg = `🏭 *ОТЧЕТ ПО ФАБРИКАМ*\n`;
tg += `📦 Товар: *${mainData.product || 'Не указан'}*\n`;
tg += `📅 Дата: ${mainData.searchDate || ''}\n\n`;

if (ranked.length === 0) {
    tg += `⚠️ Список фабрик пуст. Проверьте формат вывода Агента.`;
}

for (const f of ranked) {
  const cleanSearchName = (f.factoryName || '').replace(/[^a-zа-я0-9]/gi, '').toLowerCase();

  // ПРИОРИТЕТ ТЕЛЕФОНА: 
  // 1. Из ответа 2-го агента (f.phoneNumber) 
  // 2. Из резервной карты старой ноды phoneMap
  // 3. Если нигде нет — "не найден"
  const phone = f.phoneNumber || f.phone || phoneMap[cleanSearchName] || 'не найден';
  const reseller = f.isLikelyReseller ? ' ⚠️ перекупщик' : '';

  tg += `${f.rank || '•'}. *${f.factoryName}* — ${f.scoreTotal || '?'}/100${reseller}\n`;
  tg += `    📞 Тел: \`${phone}\` \n`;
  tg += `    💰 ${f.fobPricePerKg || '?'} | ⏱ ${f.leadTimeDays || '?'}\n`;
  tg += `    📝 ${f.recommendation || ''}\n\n`;
}

// 5. ВЫХОД ДЛЯ СЛЕДУЮЩИХ НОД (Включая Google Sheets)
return {
  telegramMessage: tg,
  sheetRows: ranked.map(f => {
    const cleanSearchName = (f.factoryName || '').replace(/[^a-zа-я0-9]/gi, '').toLowerCase();
    const phone = f.phoneNumber || f.phone || phoneMap[cleanSearchName] || 'не найден';

    return {
      date: mainData.searchDate,
      product: mainData.product,
      factoryName: f.factoryName,
      phone: phone,
      score: f.scoreTotal || f.rating || 0,
      price: f.fobPricePerKg || '',
      moq: typeof f.moq === 'object' ? JSON.stringify(f.moq) : (f.moq || ''),
      leadTime: f.leadTimeDays || ''
    };
  })
};

const base = $input.first().json;
let msg = (base.telegramMessage || '').trim();

// Если текст случайно склеился сам с собой 2 раза подряд — убираем дубль
const normalized = msg.replace(/\r\n/g, '\n');
const lines = normalized.split('\n');
const half = lines.length / 2;

if (
  Number.isInteger(half) &&
  lines.slice(0, half).join('\n').trim() === lines.slice(half).join('\n').trim()
) {
  msg = lines.slice(0, half).join('\n').trim();
}

return [
  {
    json: {
      telegramMessage: msg
    }
  }
];

const base = $input.first().json;
const rows = base.sheetRows || [];

return rows.map(row => ({
  json: {
    searchDate: row.date || '',
    product: row.product || base.product || '',
    factoryName: row.factoryName || '',
    phone: row.phone || '',
    score: row.score || 0,
    price: row.price || '',
    moq: row.moq || '',
    leadTime: row.leadTime || '',
  }
}));
